create or replace function app.profit_distribution_reconciliation(p_distribution_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare d public.profit_distributions%rowtype;v_revenue numeric:=0;v_expense numeric:=0;v_accounting_profit numeric:=0;v_eligible_bps integer:=0;v_allocated numeric:=0;v_paid numeric:=0;begin if not(app.has_permission('profit_distributions.view') or app.has_permission('profit_distributions.create') or app.has_permission('profit_distributions.approve') or app.has_permission('profit_distribution_payments.view')) then raise exception 'Missing profit distribution permission.' using errcode='42501';end if;select * into d from public.profit_distributions where id=p_distribution_id;if d.id is null then raise exception 'Distribution not found.' using errcode='P0002';end if;select max(amount) filter(where line_key='revenue_total'),max(amount) filter(where line_key='expense_total') into v_revenue,v_expense from public.financial_line_items where financial_report_version_id=d.financial_report_version_id;if v_revenue is null or v_expense is null then raise exception 'Canonical financial totals are missing.' using errcode='23514';end if;v_accounting_profit:=greatest(v_revenue-v_expense,0);v_eligible_bps:=app.eligible_ownership_bps_at_cutoff(d.offering_id,app.accounting_period_cutoff(d.period_end));select coalesce(sum(allocation_amount) filter(where status<>'cancelled'),0),coalesce(sum(allocation_amount) filter(where status='paid'),0) into v_allocated,v_paid from public.profit_distribution_allocations where distribution_id=d.id;return jsonb_build_object('distribution_id',d.id,'period_start',d.period_start,'period_end',d.period_end,'status',d.status,'revenue_total',v_revenue,'expense_total',v_expense,'accounting_net_profit',v_accounting_profit,'program_opex_rate_bps',d.opex_rate_bps,'program_opex_amount',d.opex_amount,'distributable_profit',d.profit_amount,'company_share_bps',d.company_share_bps,'investor_cap_bps',d.investor_pool_bps,'eligible_investor_bps',v_eligible_bps,'investor_pool_amount',d.investor_pool_amount,'company_retained_amount',greatest(d.profit_amount-d.investor_pool_amount,0),'allocated_amount',v_allocated,'paid_amount',v_paid,'outstanding_amount',greatest(v_allocated-v_paid,0),'allocation_matches_pool',v_allocated=d.investor_pool_amount);end$$;revoke all on function app.profit_distribution_reconciliation(uuid) from public,anon;grant execute on function app.profit_distribution_reconciliation(uuid) to authenticated;